function validate([nums]) {
  if (!Array.isArray(nums) || nums.length !== 3) return 'nums must hold exactly 3 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 127)) return 'Each value is an integer from 1 to 127.';
  return null;
}

