  for (let i = 0; i < 3; i++)
    for (let j = 0; j < 3; j++)
      for (let k = 0; k < 3; k++) {
        if (i === j || j === k || i === k) continue;
        const text = nums[i].toString(2) + nums[j].toString(2) + nums[k].toString(2);
        best = Math.max(best, parseInt(text, 2));
