function generate(rand, size) {
  const pick = () => {
    if (size === 'large') return 1 + Math.floor(rand() * 127);
    const r = rand();
    if (r < 0.3) return 1 + Math.floor(rand() * 8);
    if (r < 0.5) return [1, 2, 3, 4, 7, 8, 16, 32, 64, 127][Math.floor(rand() * 10)];
    return 1 + Math.floor(rand() * 127);
  };
  const nums = [pick(), pick(), pick()];
  // Repeated values are allowed, so sometimes copy one in.
  if (rand() < 0.2) nums[1] = nums[0];
  return [nums];
}
